'use client';

import React, { useState } from 'react';
import { CreditCard, Lock, ArrowRight, Loader2, Trash2 } from 'lucide-react';
import { CartItem } from '../types';
import { formatCurrency } from '@/utils';

interface CheckoutFormProps {
    items: CartItem[];
    onSuccess: (email: string) => void;
    onRemove?: (id: string) => void;
}

export const CheckoutForm: React.FC<CheckoutFormProps> = ({ items, onSuccess, onRemove }) => {
    const [email, setEmail] = useState('');
    const [isProcessing, setIsProcessing] = useState(false);

    const subtotal = items.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!email) return alert('Please enter your email');
        if (items.length === 0) return alert('Your cart is empty');

        setIsProcessing(true);
        // Simulate payment delay
        await new Promise(resolve => setTimeout(resolve, 2000));
        setIsProcessing(false);
        onSuccess(email);
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-start">
            {/* Purchase Summary */}
            <div className="space-y-8 bg-white p-8 rounded-3xl border border-slate-100 shadow-sm order-2 lg:order-1">
                <h3 className="text-xl font-black text-slate-900 tracking-tight">Order Summary</h3>

                <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                    {items.map((item, idx) => (
                        <div key={`${item.id}-${idx}`} className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100 group">
                            <img src={item.image} alt={item.name} className="w-16 h-16 object-cover rounded-xl" />
                            <div className="flex-1 min-w-0">
                                <h4 className="text-sm font-black text-slate-900 truncate">{item.name}</h4>
                                <div className="flex flex-wrap gap-1 mt-1">
                                    {Object.entries(item.selections).map(([key, value]) => (
                                        <span key={key} className="text-[10px] font-bold text-slate-400 bg-white px-1.5 py-0.5 rounded border border-slate-100 uppercase">
                                            {key}: {value}
                                        </span>
                                    ))}
                                </div>
                                <p className="text-[10px] font-bold text-slate-500 mt-1">Qty: {item.quantity}</p>
                            </div>
                            <div className="text-right flex flex-col items-end gap-2">
                                <p className="text-sm font-black text-slate-900">{formatCurrency(item.price * item.quantity)}</p>
                                {onRemove && (
                                    <button
                                        onClick={() => onRemove(item.id)}
                                        className="text-slate-300 hover:text-rose-500 transition-colors"
                                    >
                                        <Trash2 size={14} />
                                    </button>
                                )}
                            </div>
                        </div>
                    ))}

                    {items.length === 0 && (
                        <div className="py-20 text-center">
                            <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">Cart is empty</p>
                            <Link href="/shop" className="text-emerald-600 text-xs font-black uppercase mt-4 block">Continue Shopping</Link>
                        </div>
                    )}
                </div>

                <div className="space-y-4 pt-4 border-t border-slate-100">
                    <div className="flex justify-between text-sm font-bold text-slate-500">
                        <span>Subtotal</span>
                        <span>{formatCurrency(subtotal)}</span>
                    </div>
                    <div className="flex justify-between text-sm font-bold text-slate-500">
                        <span>Tax</span>
                        <span>$0.00</span>
                    </div>
                    <div className="flex justify-between text-xl font-black text-slate-900 pt-4 border-t border-slate-100">
                        <span>Total Due</span>
                        <span>{formatCurrency(subtotal)}</span>
                    </div>
                </div>

                <div className="p-4 bg-blue-50/50 rounded-2xl flex items-start gap-3">
                    <Lock className="text-blue-600 w-5 h-5 shrink-0" />
                    <p className="text-[10px] font-bold text-blue-800 leading-relaxed uppercase tracking-wider">
                        Secure 256-bit encrypted checkout. Your data is protected by industry-standard security protocols.
                    </p>
                </div>
            </div>

            {/* Payment Details */}
            <form onSubmit={handleSubmit} className="space-y-8 order-1 lg:order-2">
                <div className="space-y-6">
                    <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Customer Email</label>
                        <input
                            required
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="john@example.com"
                            className="w-full h-14 px-4 bg-white border border-slate-200 rounded-2xl font-black text-slate-900 focus:border-emerald-600 focus:ring-4 focus:ring-emerald-600/10 transition-all outline-none"
                        />
                    </div>

                    <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Card Details</label>
                        <div className="space-y-4">
                            <div className="relative">
                                <CreditCard className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                                <input
                                    type="text"
                                    placeholder="4242 4242 4242 4242"
                                    defaultValue="4242 4242 4242 4242"
                                    className="w-full h-14 pl-12 pr-4 bg-white border border-slate-200 rounded-2xl font-black text-slate-900 focus:border-emerald-600 focus:ring-4 focus:ring-emerald-600/10 transition-all outline-none"
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <input
                                    type="text"
                                    placeholder="MM / YY"
                                    defaultValue="12 / 26"
                                    className="h-14 px-4 bg-white border border-slate-200 rounded-2xl font-black text-slate-900 focus:border-emerald-600 focus:ring-4 focus:ring-emerald-600/10 transition-all outline-none"
                                />
                                <input
                                    type="text"
                                    placeholder="CVC"
                                    defaultValue="123"
                                    className="h-14 px-4 bg-white border border-slate-200 rounded-2xl font-black text-slate-900 focus:border-emerald-600 focus:ring-4 focus:ring-emerald-600/10 transition-all outline-none"
                                />
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col gap-4">
                    <button
                        type="submit"
                        disabled={isProcessing || items.length === 0}
                        className="w-full h-16 bg-emerald-600 shadow-xl shadow-emerald-100 text-white rounded-3xl flex items-center justify-center gap-3 text-sm font-black uppercase tracking-widest hover:bg-emerald-700 active:scale-95 transition-all disabled:opacity-50"
                    >
                        {isProcessing ? (
                            <>
                                <Loader2 className="animate-spin w-5 h-5" />
                                Verifying Payment...
                            </>
                        ) : (
                            <>
                                Pay {formatCurrency(subtotal)} Now
                                <ArrowRight size={18} />
                            </>
                        )}
                    </button>
                    <div className="flex items-center justify-center gap-6 mt-4 opacity-30 grayscale saturate-0">
                        <img src="https://upload.wikimedia.org/wikipedia/commons/b/b5/PayPal.svg" alt="PayPal" className="h-4" />
                        <img src="https://upload.wikimedia.org/wikipedia/commons/0/04/Visa.svg" alt="Visa" className="h-3" />
                        <img src="https://upload.wikimedia.org/wikipedia/commons/2/2a/Mastercard-logo.svg" alt="Mastercard" className="h-6" />
                    </div>
                </div>
            </form>
        </div>
    );
};

// Internal Link helper (since it's used in the empty state)
import Link from 'next/link';
